const b = $input.first().json.body || $input.first().json;
let phone = String(b.customer?.phone || '').replace(/[^0-9]/g, '');
if (phone.length === 10 && phone.startsWith('3')) phone = '57' + phone;
const msg = `¡Hola ${b.customer?.name || ''}! Tu pedido #${b.order_number} ya va en camino 🚚\n\nGuía Coordinadora: *${b.guia}*\nSíguelo aquí: ${b.tracking_url}`;
return [{ json: { phone, message: msg, order_number: b.order_number, guia: b.guia } }];
